import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import path from 'node:path';import {load} from 'cheerio/slim';import {parseContent,YAML} from '../../scripts/source-project.mjs';import {run} from '../../engine/pipeline.mjs';
const artifact=path.resolve('artifacts/platform/ultimate-installed'),temp=await mkdtemp(path.join(tmpdir(),'ultimate-authoring-'));
try{await cp(path.join(artifact,'project'),temp,{recursive:true});for(const name of ['component-addon-navigation.js','component-export.mjs','component-markup.mjs'])await cp(new URL('../../scripts/'+name,import.meta.url),path.join(temp,'scripts',name));const file=path.join(temp,'content/pages/menu-horizontal.md'),parsed=parseContent(await readFile(file,'utf8'),file);assert.match(parsed.body,/Explore our workshop services/);parsed.meta.title='Authored navigation workshop';await writeFile(file,'---\n'+YAML.stringify(parsed.meta)+'---\n\n'+parsed.body.replace('Explore our workshop services','Revised workshop services'));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});const $=load(await readFile(path.join(temp,'output/menu-horizontal/index.html'),'utf8'));assert.match($('body').text(),/Revised workshop services/);assert.match($('title').text(),/Authored navigation workshop/);assert.equal($('script[data-cloner-component=addon-navigation]').length,1);const result={markdown:true,titleFrontmatter:true,nativeBuild:true,selectiveRuntime:true,scope:'Page prose and title authoring; shared header/footer and navigation-item authoring remain separate gates.'};await writeFile(path.join(artifact,'ultimate-authoring-check.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result));}finally{await rm(temp,{recursive:true,force:true});}
